/*
 * Test of the SLH-DSA functions in C (slhdsa.c):
 *
 * - the nodes of test_slhdsa_vectors.h (generated by make_slhdsa_vectors.py),
 *   which come from the vectors of NIST and of SP 800-230: PK.root, and
 *   nodes of the authentication paths in signatures, of XMSS and FORS trees;
 * - wots_pkGen (Algorithm 6) and the parent nodes (Algorithms 9 and 15)
 *   rebuilt from slhdsa_thash() and slhdsa_chain(), for all the hash
 *   families, n and lg_w;
 * - the checks of the parameters.
 *
 * The test is linked with each build of slhdsa.c:
 * - slhdsa.c (portable),
 * - slhdsa_shani.c (TEST_SLHDSA_SHA_NI): SHA-256 with the Intel SHA
 *   extensions. On a CPU without them that test does nothing, unless
 *   SLHDSA_REQUIRE_SHA_NI is set;
 * - slhdsa_avx2_bmi2.c (TEST_SLHDSA_AVX2): 4 SHAKE or 8 SHA-256 hashes at once.
 *   On a CPU without AVX2, BMI1 and BMI2 that test does nothing, unless
 *   SLHDSA_REQUIRE_AVX2 is set;
 * - slhdsa_armv8.c (TEST_SLHDSA_ARMV8): SHA-256 with the ARMv8 Cryptography
 *   Extensions. On a CPU without them that test does nothing, unless
 *   SLHDSA_REQUIRE_ARMV8 is set.
 */

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "common.h"
#include "errors.h"

#if defined(TEST_SLHDSA_SHA_NI)
#include <cpuid.h>
#endif

#if defined(TEST_SLHDSA_ARMV8) && defined(__linux__)
#include <sys/auxv.h>
#elif defined(TEST_SLHDSA_ARMV8) && defined(_M_ARM64)
#include <windows.h>
#endif

/* As in slhdsa.c */
enum { SLHDSA_SHAKE = 0, SLHDSA_SHA2 = 1 };
enum { WOTS_HASH = 0, WOTS_PK = 1, TREE = 2, FORS_TREE = 3, WOTS_PRF = 5, FORS_PRF = 6 };

#define N_MAX       32
#define LEN_MAX     133
#define ADRS_LEN    32

/** The functions of slhdsa.c **/
int slhdsa_thash(unsigned family, size_t n, unsigned lg_w, uint8_t *out,
                 const uint8_t *pk_seed, const uint8_t adrs[ADRS_LEN],
                 const uint8_t *m, size_t m_len);
int slhdsa_chain(unsigned family, size_t n, unsigned lg_w, uint8_t *out,
                 const uint8_t *pk_seed, const uint8_t adrs[ADRS_LEN],
                 const uint8_t *x, unsigned i, unsigned s);
int slhdsa_wots_chains(unsigned family, size_t n, unsigned lg_w, uint8_t *out,
                       const uint8_t *sk_seed, const uint8_t *pk_seed,
                       const uint8_t adrs[ADRS_LEN], const uint8_t *x,
                       const uint8_t *start, const uint8_t *steps, size_t len);
int slhdsa_xmss_node(unsigned family, size_t n, unsigned lg_w, uint8_t *out,
                     const uint8_t *sk_seed, const uint8_t *pk_seed,
                     const uint8_t adrs[ADRS_LEN], uint32_t i, unsigned z);
int slhdsa_fors_node(unsigned family, size_t n, unsigned lg_w, uint8_t *out,
                     const uint8_t *sk_seed, const uint8_t *pk_seed,
                     const uint8_t adrs[ADRS_LEN], uint32_t i, unsigned z);

typedef enum { NODE_XMSS, NODE_FORS } NodeKind;

typedef struct {
    const char *name;
    unsigned family;
    unsigned n;
    unsigned lg_w;
    NodeKind kind;
    const char *sk_seed;    /* the byte strings are in hex */
    const char *pk_seed;
    const char *adrs;
    uint32_t i;
    unsigned z;
    const char *node;
} NodeVector;

#include "test_slhdsa_vectors.h"

static void check(int condition, const char *what)
{
    if (!condition) {
        printf("Failed: %s\n", what);
        exit(1);
    }
}

static unsigned hex_digit(char c)
{
    if (c >= '0' && c <= '9')
        return (unsigned)(c - '0');
    check(c >= 'a' && c <= 'f', "hex digit");
    return (unsigned)(c - 'a' + 10);
}

static void unhex(uint8_t *out, size_t len, const char *hex)
{
    size_t i;

    check(strlen(hex) == 2*len, "length of a hex string");
    for (i = 0; i < len; i++)
        out[i] = (uint8_t)(hex_digit(hex[2*i]) << 4 | hex_digit(hex[2*i + 1]));
}

/** The nodes of the vectors of NIST and of SP 800-230 **/
static void test_node_vectors(void)
{
    size_t v;

    for (v = 0; v < sizeof node_vectors / sizeof node_vectors[0]; v++) {
        const NodeVector *tv = &node_vectors[v];
        uint8_t sk_seed[N_MAX], pk_seed[N_MAX], adrs[ADRS_LEN], node[N_MAX];
        uint8_t out[N_MAX];
        uint8_t adrs_copy[ADRS_LEN];
        int res;

        unhex(sk_seed, tv->n, tv->sk_seed);
        unhex(pk_seed, tv->n, tv->pk_seed);
        unhex(adrs, ADRS_LEN, tv->adrs);
        unhex(node, tv->n, tv->node);
        memcpy(adrs_copy, adrs, ADRS_LEN);

        if (tv->kind == NODE_XMSS)
            res = slhdsa_xmss_node(tv->family, tv->n, tv->lg_w, out, sk_seed, pk_seed, adrs, tv->i, tv->z);
        else
            res = slhdsa_fors_node(tv->family, tv->n, tv->lg_w, out, sk_seed, pk_seed, adrs, tv->i, tv->z);
        check(res == 0, tv->name);
        check(memcmp(out, node, tv->n) == 0, tv->name);
        check(memcmp(adrs, adrs_copy, ADRS_LEN) == 0, "the address is not modified");
    }
}

/** The address functions of FIPS 205 (Table 1), on 32-byte arrays **/
static void set_word(uint8_t adrs[ADRS_LEN], unsigned offset, uint32_t value)
{
    adrs[offset] = (uint8_t)(value >> 24);
    adrs[offset + 1] = (uint8_t)(value >> 16);
    adrs[offset + 2] = (uint8_t)(value >> 8);
    adrs[offset + 3] = (uint8_t)value;
}

static void set_type_and_clear(uint8_t adrs[ADRS_LEN], uint32_t type)
{
    set_word(adrs, 16, type);
    memset(adrs + 20, 0, 12);
}

/* The parameters of the tests that rebuild the nodes */
typedef struct {
    unsigned family;
    unsigned n;
    unsigned lg_w;
} Params;

static const Params all_params[] = {
    { SLHDSA_SHAKE, 16, 4 }, { SLHDSA_SHAKE, 24, 4 }, { SLHDSA_SHAKE, 32, 4 },
    { SLHDSA_SHAKE, 16, 2 }, { SLHDSA_SHAKE, 24, 3 }, { SLHDSA_SHAKE, 32, 2 },
    { SLHDSA_SHA2, 16, 4 }, { SLHDSA_SHA2, 24, 4 }, { SLHDSA_SHA2, 32, 4 },
    { SLHDSA_SHA2, 16, 2 }, { SLHDSA_SHA2, 24, 3 }, { SLHDSA_SHA2, 32, 2 },
};

/* The seeds of the tests that rebuild the nodes (set by main) */
static uint8_t sk_seed[N_MAX];
static uint8_t pk_seed[N_MAX];

/* len (Equations 5.1 to 5.4): 35, 51 and 67 for lg_w = 4, 68 for n = 16 and
 * lg_w = 2, 67 for n = 24 and lg_w = 3, 133 for n = 32 and lg_w = 2 */
static unsigned wots_len(unsigned n, unsigned lg_w)
{
    static const unsigned lens[3][3] = {
        /* lg_w = 2, 3, 4 */
        { 68, 0, 35 },      /* n = 16 */
        { 0, 67, 51 },      /* n = 24 */
        { 133, 0, 67 },     /* n = 32 */
    };
    unsigned len = lens[(n - 16) / 8][lg_w - 2];

    check(len != 0, "parameters with a known len");
    return len;
}

/* An XMSS (layer 1, tree 5) or FORS (FORS_TREE, key pair 3) address */
static void base_adrs(uint8_t adrs[ADRS_LEN], NodeKind kind)
{
    memset(adrs, 0, ADRS_LEN);
    if (kind == NODE_XMSS) {
        set_word(adrs, 0, 1);
        set_word(adrs, 12, 5);
    } else {
        set_word(adrs, 12, 5);
        set_type_and_clear(adrs, FORS_TREE);
        set_word(adrs, 20, 3);
    }
}

/*
 * The leaf i of an XMSS tree, as wots_pkGen (Algorithm 6) with
 * slhdsa_thash() and slhdsa_chain(), and xmss_node (Algorithm 9) with z = 0
 */
static void test_wots_pkgen(const Params *p, uint32_t i)
{
    uint8_t adrs[ADRS_LEN], sk_adrs[ADRS_LEN], wotspk_adrs[ADRS_LEN];
    uint8_t sk[N_MAX], tmp[LEN_MAX * N_MAX], pk[N_MAX], node[N_MAX];
    unsigned j, n = p->n, len = wots_len(p->n, p->lg_w), w = 1U << p->lg_w;

    /* ADRS of type WOTS_HASH, for the key pair i (Algorithm 9, lines 2 and 3) */
    base_adrs(adrs, NODE_XMSS);
    set_type_and_clear(adrs, WOTS_HASH);
    set_word(adrs, 20, i);

    memcpy(sk_adrs, adrs, ADRS_LEN);
    set_type_and_clear(sk_adrs, WOTS_PRF);
    set_word(sk_adrs, 20, i);
    for (j = 0; j < len; j++) {
        set_word(sk_adrs, 24, j);
        /* PRF(PK.seed, SK.seed, skADRS) is F(PK.seed, skADRS, SK.seed) */
        check(slhdsa_thash(p->family, n, p->lg_w, sk, pk_seed, sk_adrs, sk_seed, n) == 0, "PRF");
        set_word(adrs, 24, j);
        check(slhdsa_chain(p->family, n, p->lg_w, tmp + j*n, pk_seed, adrs, sk, 0, w - 1) == 0, "chain");
    }
    memcpy(wotspk_adrs, adrs, ADRS_LEN);
    set_type_and_clear(wotspk_adrs, WOTS_PK);
    set_word(wotspk_adrs, 20, i);
    check(slhdsa_thash(p->family, n, p->lg_w, pk, pk_seed, wotspk_adrs, tmp, (size_t)len * n) == 0, "T_len");

    base_adrs(adrs, NODE_XMSS);
    check(slhdsa_xmss_node(p->family, n, p->lg_w, node, sk_seed, pk_seed, adrs, i, 0) == 0, "xmss_node");
    check(memcmp(node, pk, n) == 0, "wots_pkGen");
}

/*
 * slhdsa_wots_chains() with chains of different lengths, against one chain
 * at a time with slhdsa_chain(): from the private values (x NULL, as in
 * wots_sign), then from them (as in wots_pkFromSig)
 */
static void test_wots_chains(const Params *p)
{
    uint8_t adrs[ADRS_LEN], sk_adrs[ADRS_LEN], before[ADRS_LEN];
    uint8_t start[LEN_MAX], steps[LEN_MAX];
    uint8_t x[LEN_MAX * N_MAX], out[LEN_MAX * N_MAX], expected[LEN_MAX * N_MAX];
    unsigned j, n = p->n, len = wots_len(p->n, p->lg_w), w = 1U << p->lg_w;

    base_adrs(adrs, NODE_XMSS);
    set_type_and_clear(adrs, WOTS_HASH);
    set_word(adrs, 20, 3);
    memcpy(before, adrs, ADRS_LEN);
    memcpy(sk_adrs, adrs, ADRS_LEN);
    set_type_and_clear(sk_adrs, WOTS_PRF);
    set_word(sk_adrs, 20, 3);

    for (j = 0; j < len; j++) {
        start[j] = (uint8_t)(j % w);
        steps[j] = (uint8_t)((7*j) % (w - start[j]));
        set_word(sk_adrs, 24, j);
        check(slhdsa_thash(p->family, n, p->lg_w, x + j*n, pk_seed, sk_adrs, sk_seed, n) == 0, "PRF");
        set_word(adrs, 24, j);
        check(slhdsa_chain(p->family, n, p->lg_w, expected + j*n, pk_seed, adrs, x + j*n, start[j], steps[j]) == 0, "chain");
    }
    memcpy(adrs, before, ADRS_LEN);

    check(slhdsa_wots_chains(p->family, n, p->lg_w, out, sk_seed, pk_seed, adrs, x, start, steps, len) == 0, "chains");
    check(memcmp(out, expected, (size_t)len * n) == 0, "chains from X");
    memset(out, 0, sizeof out);
    check(slhdsa_wots_chains(p->family, n, p->lg_w, out, sk_seed, pk_seed, adrs, NULL, start, steps, len) == 0, "chains");
    check(memcmp(out, expected, (size_t)len * n) == 0, "chains from the private values");
    check(memcmp(adrs, before, ADRS_LEN) == 0, "adrs not modified");

    /* The checks: len chains, start + steps up to w - 1, X or SK.seed */
    check(slhdsa_wots_chains(p->family, n, p->lg_w, out, sk_seed, pk_seed, adrs, x, start, steps, len - 1) == ERR_VALUE, "len - 1");
    check(slhdsa_wots_chains(p->family, n, p->lg_w, out, NULL, pk_seed, adrs, NULL, start, steps, len) == ERR_NULL, "no X nor SK.seed");
    check(slhdsa_wots_chains(p->family, n, p->lg_w, out, NULL, pk_seed, adrs, x, start, steps, len) == 0, "X without SK.seed");
    steps[len - 1] = (uint8_t)(w - start[len - 1]);
    check(slhdsa_wots_chains(p->family, n, p->lg_w, out, sk_seed, pk_seed, adrs, x, start, steps, len) == ERR_VALUE, "start + steps = w");
}

/* chain(X, i, s) is chain(chain(X, i, t), i + t, s - t) */
static void test_chain(const Params *p)
{
    uint8_t adrs[ADRS_LEN], x[N_MAX], all[N_MAX], part[N_MAX];
    unsigned n = p->n, w = 1U << p->lg_w, t;

    base_adrs(adrs, NODE_XMSS);
    set_word(adrs, 24, 7);
    memcpy(x, sk_seed, n);
    check(slhdsa_chain(p->family, n, p->lg_w, all, pk_seed, adrs, x, 1, w - 2) == 0, "chain");

    for (t = 0; t <= w - 2; t++) {
        check(slhdsa_chain(p->family, n, p->lg_w, part, pk_seed, adrs, x, 1, t) == 0, "chain");
        check(slhdsa_chain(p->family, n, p->lg_w, part, pk_seed, adrs, part, 1 + t, w - 2 - t) == 0, "chain");
        check(memcmp(part, all, n) == 0, "chain in two pieces");
    }

    /* No steps: X itself */
    check(slhdsa_chain(p->family, n, p->lg_w, part, pk_seed, adrs, x, w - 1, 0) == 0, "chain");
    check(memcmp(part, x, n) == 0, "chain with no steps");
}

/*
 * The leaf i of a FORS tree, as fors_skGen (Algorithm 14) and F
 * (Algorithm 15, lines 2 to 5), with slhdsa_thash()
 */
static void test_fors_leaf(const Params *p, uint32_t i)
{
    uint8_t adrs[ADRS_LEN], sk_adrs[ADRS_LEN], sk[N_MAX], leaf[N_MAX], node[N_MAX];
    unsigned n = p->n;

    base_adrs(adrs, NODE_FORS);
    memcpy(sk_adrs, adrs, ADRS_LEN);
    set_type_and_clear(sk_adrs, FORS_PRF);
    set_word(sk_adrs, 20, 3);
    set_word(sk_adrs, 28, i);
    check(slhdsa_thash(p->family, n, p->lg_w, sk, pk_seed, sk_adrs, sk_seed, n) == 0, "PRF");

    set_word(adrs, 24, 0);
    set_word(adrs, 28, i);
    check(slhdsa_thash(p->family, n, p->lg_w, leaf, pk_seed, adrs, sk, n) == 0, "F");

    base_adrs(adrs, NODE_FORS);
    check(slhdsa_fors_node(p->family, n, p->lg_w, node, sk_seed, pk_seed, adrs, i, 0) == 0, "fors_node");
    check(memcmp(node, leaf, n) == 0, "FORS leaf");
}

/*
 * The node i of height z, as H of its two children
 * (Algorithm 9, lines 6 to 11, and Algorithm 15, lines 7 to 11)
 */
static void test_parent(const Params *p, NodeKind kind, uint32_t i, unsigned z)
{
    uint8_t adrs[ADRS_LEN], children[2 * N_MAX], parent[N_MAX], node[N_MAX];
    unsigned n = p->n;
    int (*func)(unsigned, size_t, unsigned, uint8_t *, const uint8_t *,
                const uint8_t *, const uint8_t *, uint32_t, unsigned);

    func = kind == NODE_XMSS ? slhdsa_xmss_node : slhdsa_fors_node;

    base_adrs(adrs, kind);
    check(func(p->family, n, p->lg_w, children, sk_seed, pk_seed, adrs, 2*i, z - 1) == 0, "left child");
    check(func(p->family, n, p->lg_w, children + n, sk_seed, pk_seed, adrs, 2*i + 1, z - 1) == 0, "right child");

    if (kind == NODE_XMSS)
        set_type_and_clear(adrs, TREE);
    set_word(adrs, 24, z);
    set_word(adrs, 28, i);
    check(slhdsa_thash(p->family, n, p->lg_w, parent, pk_seed, adrs, children, 2*n) == 0, "H");

    base_adrs(adrs, kind);
    check(func(p->family, n, p->lg_w, node, sk_seed, pk_seed, adrs, i, z) == 0, "node");
    check(memcmp(node, parent, n) == 0, kind == NODE_XMSS ? "XMSS parent" : "FORS parent");
}

static void test_rebuilt_nodes(void)
{
    size_t k;
    unsigned z;

    for (k = 0; k < sizeof all_params / sizeof all_params[0]; k++) {
        const Params *p = &all_params[k];

        test_chain(p);
        test_wots_chains(p);
        test_wots_pkgen(p, 0);
        test_wots_pkgen(p, 5);
        test_fors_leaf(p, 0);
        test_fors_leaf(p, 13);
        for (z = 1; z <= 2; z++)
            test_parent(p, NODE_XMSS, 3, z);
        /* With AVX2, the FORS subtrees of height 2 or more are computed 4 at once */
        for (z = 1; z <= 5; z++) {
            test_parent(p, NODE_FORS, 0, z);
            test_parent(p, NODE_FORS, 7, z);
        }
    }
}

/** The checks of the parameters **/
static void test_errors(void)
{
    uint8_t adrs[ADRS_LEN], out[N_MAX], m[(LEN_MAX + 1) * N_MAX];
    unsigned family;

    memset(adrs, 0, sizeof adrs);
    memset(m, 0, sizeof m);

    for (family = SLHDSA_SHAKE; family <= SLHDSA_SHA2; family++) {
        /* NULL pointers */
        check(slhdsa_thash(family, 16, 4, NULL, pk_seed, adrs, m, 16) == ERR_NULL, "thash out NULL");
        check(slhdsa_thash(family, 16, 4, out, NULL, adrs, m, 16) == ERR_NULL, "thash pk_seed NULL");
        check(slhdsa_thash(family, 16, 4, out, pk_seed, NULL, m, 16) == ERR_NULL, "thash adrs NULL");
        check(slhdsa_thash(family, 16, 4, out, pk_seed, adrs, NULL, 16) == ERR_NULL, "thash m NULL");
        check(slhdsa_chain(family, 16, 4, out, pk_seed, adrs, NULL, 0, 1) == ERR_NULL, "chain x NULL");
        check(slhdsa_xmss_node(family, 16, 4, out, NULL, pk_seed, adrs, 0, 0) == ERR_NULL, "xmss_node sk_seed NULL");
        check(slhdsa_xmss_node(family, 16, 4, out, sk_seed, NULL, adrs, 0, 0) == ERR_NULL, "xmss_node pk_seed NULL");
        check(slhdsa_fors_node(family, 16, 4, out, NULL, pk_seed, adrs, 0, 0) == ERR_NULL, "fors_node sk_seed NULL");
        check(slhdsa_fors_node(family, 16, 4, NULL, sk_seed, pk_seed, adrs, 0, 0) == ERR_NULL, "fors_node out NULL");

        /* n and lg_w */
        check(slhdsa_thash(family, 20, 4, out, pk_seed, adrs, m, 20) == ERR_VALUE, "n = 20");
        check(slhdsa_thash(family, 64, 4, out, pk_seed, adrs, m, 64) == ERR_VALUE, "n = 64");
        check(slhdsa_thash(family, 16, 1, out, pk_seed, adrs, m, 16) == ERR_VALUE, "lg_w = 1");
        check(slhdsa_thash(family, 16, 5, out, pk_seed, adrs, m, 16) == ERR_VALUE, "lg_w = 5");

        /* The length of M: a multiple of n, up to LEN_MAX * N_MAX */
        check(slhdsa_thash(family, 16, 4, out, pk_seed, adrs, m, 0) == ERR_VALUE, "empty M");
        check(slhdsa_thash(family, 16, 4, out, pk_seed, adrs, m, 17) == ERR_VALUE, "M of 17 bytes");
        check(slhdsa_thash(family, 16, 4, out, pk_seed, adrs, m, LEN_MAX * N_MAX) == 0, "longest M");
        check(slhdsa_thash(family, 16, 4, out, pk_seed, adrs, m, LEN_MAX * N_MAX + 16) == ERR_VALUE, "M too long");

        /* chain: i + s up to w - 1 */
        check(slhdsa_chain(family, 16, 4, out, pk_seed, adrs, m, 15, 0) == 0, "chain i = 15");
        check(slhdsa_chain(family, 16, 4, out, pk_seed, adrs, m, 16, 0) == ERR_VALUE, "chain i = 16");
        check(slhdsa_chain(family, 16, 4, out, pk_seed, adrs, m, 5, 11) == ERR_VALUE, "chain i + s = 16");
        check(slhdsa_chain(family, 16, 2, out, pk_seed, adrs, m, 1, 3) == ERR_VALUE, "chain i + s = 4 (lg_w = 2)");

        /* The heights and the indices of the nodes */
        check(slhdsa_xmss_node(family, 16, 4, out, sk_seed, pk_seed, adrs, 0, 23) == ERR_VALUE, "XMSS z = 23");
        check(slhdsa_xmss_node(family, 16, 4, out, sk_seed, pk_seed, adrs, 1UL << 21, 1) == ERR_VALUE, "XMSS i too large");
        check(slhdsa_fors_node(family, 16, 4, out, sk_seed, pk_seed, adrs, 0, 26) == ERR_VALUE, "FORS z = 26");
        check(slhdsa_fors_node(family, 16, 4, out, sk_seed, pk_seed, adrs, 1UL << 28, 1) == ERR_VALUE, "FORS i too large");
        check(slhdsa_fors_node(family, 16, 4, out, sk_seed, pk_seed, adrs, (1UL << 28) - 1, 1) == 0, "FORS last i");
    }

    /* The hash family */
    check(slhdsa_thash(2, 16, 4, out, pk_seed, adrs, m, 16) == ERR_VALUE, "family 2");
    check(slhdsa_xmss_node(2, 16, 4, out, sk_seed, pk_seed, adrs, 0, 0) == ERR_VALUE, "family 2");
}

/* Return 1 if the test must be skipped, as the CPU lacks the instructions */
static int skip(void)
{
#if defined(TEST_SLHDSA_SHA_NI) || defined(TEST_SLHDSA_AVX2) || defined(TEST_SLHDSA_ARMV8)
    const char *required;
    int supported;

#if defined(TEST_SLHDSA_SHA_NI)
    unsigned eax, ebx = 0, ecx, edx;

    /* CPUID leaf 7, EBX bit 29 */
    supported = __get_cpuid_count(7, 0, &eax, &ebx, &ecx, &edx) && (ebx & (1U << 29));
    required = getenv("SLHDSA_REQUIRE_SHA_NI");
#define FEATURES "the SHA extensions"
#elif defined(TEST_SLHDSA_ARMV8)
    /* As have_sha256_armv8() in cpuid.c */
#if defined(__aarch64__) && defined(__linux__)
    supported = (getauxval(AT_HWCAP) & (1UL << 6)) ? 1 : 0;     /* HWCAP_SHA2 */
#elif defined(__aarch64__) && defined(__APPLE__)
    supported = 1;
#elif defined(_M_ARM64)
    supported = IsProcessorFeaturePresent(PF_ARM_V8_CRYPTO_INSTRUCTIONS_AVAILABLE) ? 1 : 0;
#else
    supported = 0;
#endif
    required = getenv("SLHDSA_REQUIRE_ARMV8");
#define FEATURES "the ARMv8 SHA-256 instructions"
#else
    supported = __builtin_cpu_supports("avx2") && __builtin_cpu_supports("bmi") &&
                __builtin_cpu_supports("bmi2");
    required = getenv("SLHDSA_REQUIRE_AVX2");
#define FEATURES "AVX2, BMI1 and BMI2"
#endif

    if (!supported) {
        /* In CI on x86-64, the test must run (the variable is set) */
        if (required && *required) {
            printf("Failed: the CPU does not support " FEATURES ", but the test is required\n");
            exit(1);
        }
        printf("Skipped: the CPU does not support " FEATURES "\n");
        return 1;
    }
#endif
    return 0;
}

int main(void)
{
    unsigned i;

    if (skip())
        return 0;

    for (i = 0; i < N_MAX; i++) {
        sk_seed[i] = (uint8_t)(3*i + 1);
        pk_seed[i] = (uint8_t)(5*i + 2);
    }

    test_errors();
    test_rebuilt_nodes();
    test_node_vectors();
    return 0;
}
